INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (67, 402, 'thermal transfer ribbons& thermal transfer labels', '../upload/image/20191016/20191016084516_37993.jpg', '<p><span style="color:#009688;font-family:&quot;font-size:14px;background-color:#F2F2F2;">thermal transfer ribbons&amp; thermal transfer labels<br/> Understanding Thermal Transfer Ribbons<br/> <br/> Thermal transfer printer alongside different thermal transfer ribbon choices<br/> If you''re planning to print labels with a thermal transfer printer, you''re going to need thermal transfer ribbons in addition to thermal transfer labels. Here''s everything you need to know about selecting the right thermal transfer ribbon for your printer and project.<br/> <br/> Ribbon Type / Wind Direction<br/> Wind directions of CSO vs CSI thermal transfer ribbons<br/> You may notice when shopping for printer ribbons that there are two categories: coated side out (CSO) and coated side in (CSI). This refers to where the ink coating is placed on the ribbons. It affects how they''re wound and fed through the printer – most printers can only take one style or the other.<br/> <br/> Coated Side Out (CSO) Ribbons<br/> Coated side out ribbons are printing ribbons that have the ink coating facing outside. Zebra&reg; thermal transfer printers typically use this type of ribbon. You''ll notice that the ink is on the outside of the ribbon roll and that it unrolls from the bottom before making contact with the print-head and label.<br/> <br/> To correctly insert this ribbon type into your printer, unroll it from the bottom and feed it underneath.<br/> <br/> Shop CSO Ribbons<br/> Coated Side In (CSI) Ribbons<br/> Coated side in ribbons are printing ribbons that have the ink facing inside. Datamax&reg; and Sato&reg; thermal transfer printers most commonly use CSI ribbons. You''ll notice that the ink is on the inside of the ribbon roll and that it unrolls from the top before making contact with the print-head and label.<br/> <br/> To correctly insert this ribbon type into your printer, unroll it from the top and feed it over.<br/> <br/> Shop CSI Ribbons&nbsp;<br/> You can also determine your ribbon type/wind direction using the tape test: Stick a piece of tape to the outside of your ribbon roll. After a few seconds, peel the tape off. If ink sticks to the tape, you were using a CSO ribbon. If no ink sticks to the tape, you were using a CSI ribbon.<br/> <br/> Ribbon Size<br/> There are a couple of criteria to consider when selecting a thermal transfer ribbon size. They are:<br/> <br/> Label width<br/> Pick the ribbon width closest to that of your most commonly used label. For example, if you''re printing a 2.5 inch wide label, you should purchase a 3.27 inch ribbon as opposed to a 4.33 inch one. Any unused ink on the thermal transfer ribbon will go to waste otherwise. You should also be conscious to buy a width that fits in your printer.<br/> <br/> Ribbon length<br/> Typically, ribbons with a shorter length are intended for desktop thermal transfer printers while the longer lengths are intended for industrial ones. Our ribbons range from 243 feet to 1,476 feet.<br/> <br/> Core size<br/> Smaller printers don''t have as much space to accommodate larger ribbon cores. While a 1 inch core is standard, smaller printers use a 0.5 inch core.<br/> <br/> <br/> Is your label size the best fit for your project? Our selection of thermal transfer roll labels includes more than 75 unique label sizes for both 1 inch and 3 inch core sizes.<br/> <br/> </span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (67, 207, 'Color Ribbon Color Ribbon (Wax/resin)', '../upload/image/20181226/20181226145956_94608.jpg', '<p></p><p>Color Ribbon Color Ribbon (Wax/resin)</p> <p>1. High opacity,vibrant colours<br/> 2. High resolution,good printing of small characters and find lines.<br/> 3. Good mechanical resistance against smearing and scratching<br/> 4. High sensitivity for increased print-head life<br/> 5. Very flexible, good results on all type of paper, cardboard and synthetic substrates and all printers equipped with near-edge print heads<br/> APPLICATION<br/> 1. Highlighting of important information<br/> 2. Product identification and differenciation by colours<br/> 3. Suitable for high quality labels in corporate colour<br/> 4. High printing speed<br/> RECOMMENDED LABEL STOCK<br/> 1.Vellum,matt-and gloss-coated paper,cast-coated paper like Chromolux<br/> 2. Cardboard materials<br/> 3. PE,PP,PS,PET and other synthetic films<br/> Resin<br/> 1. High opacity,vibrant colours<br/> 2. High resolution,good printing of small characters and find lines.<br/> 3. High sensitivity for increased print-head life<br/> 4. Very flexible, good results on all type of paper and cardboard substrates<br/> APPLICATION<br/> 1. Highlighting of important information<br/> 2. Product identification and differenciation by colours<br/> 3. Suitable for high quality labels in corporate colour<br/> 4. High printing speed<br/> RECOMMENDED LABEL STOCK<br/> 1.Vellum,matt-and gloss-coated paper,cast-coated paper like Chromolux<br/> 2. Cardboard materials<br/> 1. High opacity,vibrant colours<br/> 2. High resolution,good printing of small characters and find lines.<br/> 3. High sensitivity for increased print-head life<br/> 4. Very flexible, good results on all type of paper and cardboard substrates<br/> APPLICATION<br/> 1. Highlighting of important information<br/> 2. Product identification and differenciation by colours<br/> 3. Suitable for high quality labels in corporate colour<br/> 4. High printing speed<br/> RECOMMENDED LABEL STOCK<br/> 1.Vellum,matt-and gloss-coated paper,cast-coated paper like Chromolux<br/> 2. Cardboard materials<br/> STYLE TYPE COLOR PANTONE COLOR NUMBER(RIBBON COLOR) <br/> WAX/RESIN BLUE 2728C<br/> 600L RESIN BLUE PROCESS BLUE C<br/> 600R RESIN RED 1788C<br/> TRH550 RESIN GERY 7543C<br/> 500G RESINI GUEEN 561C<br/> 601G RESIN GRENE 340C<br/> TRW550 RESIN WHITE</p> <p><br/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (67, 206, 'Wash Care Ribbon', '../upload/image/20181226/20181226145900_10694.jpg', '<p>Wash Care Ribbon <br/> Feature:<br/> Superior Launderability and heat resistance<br/> Applicable to various types of labels and tags<br/> High definition<br/> Technical parameters:<br/> Test Item: Unit Test equipment Standard<br/> Total thickness: um Thickness tester 5.9+_0.2<br/> Ink thickness um Thickness tester 1.4+_0.2<br/> Electrostatic Kv Siatic Tester 0<br/> Optical density D Transmission Type Density Spectrometer &gt; =1.3<br/> Color density DB Reflex density spectrometer &gt;=1.8<br/> Application Field:<br/> Garment industry wash care label,garment material label,carpet.<br/> Introduction:<br/> The advanced a-coating technology makes the products have superior anti-static property and excellent print quality.ZL802 have the good print capability and the extensive print range by using the high property printer and the simplified tabletop printer.The high quality raw materials we choose can make the printed picture have superior heat resistance,ironing resistance and launderability.<br/> Print material:<br/> Recommended substrates;<br/> Nylon,terylene,polyester fiber,rayon,synthetic,fiber.<br/> <br/></p>', '2026-09-06 20:58:45');
