INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (67, 204, 'Near-Edge Wax&amp;resin-ribbon', '../upload/image/20181226/20181226145700_75852.jpg', '<p></p><p>Near-Edge Wax&amp;resin-ribbon <br/> Feature:<br/> Superior abrasion resistance<br/> Extensive label adaptability<br/> Stable quality of product<br/> Low print energy can extend the life of protect print head.<br/> Anti-static back coating can protectprint head effectively.<br/> Technical parameters:<br/> Test Item: Unit Test equipment Standard<br/> Total thickness: um Thickness tester 6.8+_0.3<br/> Ink thickness um Thickness tester 1.0+_0.3<br/> Electrostatic Kv Siatic Tester &lt;=0.15<br/> Optical density D Transmission Type Density Spectrometer &gt;=1.2<br/> Color density<br/> DB Reflex density spectrometer &gt;=2.4<br/> Application Field:<br/> Logistical Label,Medical label,retail tag,shelf and bin label,automotive label,<br/> Biochemical label,blood label,hang tag.packing label,train tickets.<br/> Shipping&amp; Receiving label.<br/> Introduction:<br/> The advanced coating technology of new generation wax/resin makes the products have the superior heat resistance,abrasion resistance,anti-static function,high stability and low noise in the printing process, have the good print quality and the better label adaptability by using the high property printer and the simplified tabletop printer,it is suitable for many different types of label stocks. the color density can be up to 2.7DB.<br/> Print material:<br/> Recommended substrates;<br/> Art paper, coated paper, uncoated paper, glossy&amp; semi glossy paper, hangtag, synthetic paper, film(PET,PP,PVC)</p> <p></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (67, 203, 'Flat Head Wax&amp;Resin ribbon (normal)', '../upload/image/20181226/20181226145606_45601.jpg', '<p></p><p>Flat Head Wax&amp;Resin ribbon (normal)<br/> Feature:<br/> Superior abrasion resistance<br/> Extensive label adaptability<br/> Stable quality of product<br/> Low print energy can extend the life of protect print head<br/> Anti-static back coating can protect print head effectively<br/> Introduction:<br/> The advanced coating technology of new generation Wax/Resin makes the products have the superior heat resistance, abrasion resistance, anti-static function, high stability and low noise in the printing process. have the good print quality and the better label adaptability by using the high property printer and the simplified tabletop printer. It is suitable for many different types of label stocks. The color density can be up to 2.7DB.<br/> Print material:<br/> Recommended substrates:<br/> art paper, coated paper, uncoated paper, glossy &amp; semi glossy paper, hangtag, synthetic paper, film(PET,PP,PVC)<br/> Application field<br/> Logistical Label, Medical Label, Retail tag, shelf and bin Label, Automotive Label,Biochemical Label, Blood Label, Hang Tag, Packing Label, Train Tickets, Shipping &amp; Receiving Label.<br/> Technical parameters:<br/> Test Item Unit Test Equipment Standard<br/> Total thickness Um Thickness Tester 7.1+0.2<br/> Ink thickness Um Thickness Tester 2.0+0.4<br/> Electrostatic K v Static Tester 0.02<br/> Optical density D Transmission Type Density Spectrometer 1.0<br/> Color density D B Reflex density spectrometer 2.7<br/> Glossiness Gs Vancometer 50</p> <p><br/></p>', '2026-09-06 20:58:45');
